package tools.pantheum.gaia.desktop.datamatrix;

/**
 * Arithmetic in GF(2^8) as Data Matrix defines it — the field the Reed-Solomon error correction
 * of ECC 200 is computed in.
 *
 * <p>The field is generated by the primitive polynomial {@code x^8 + x^5 + x^3 + x^2 + 1}
 * ({@code 0x12D}). That choice is symbology-specific: QR Code uses {@code 0x11D} in the same
 * field size, and a decoder using the wrong polynomial produces plausible-looking nonsense rather
 * than an obvious failure, so it is worth stating explicitly.
 *
 * <p>Addition and subtraction in a binary field are both XOR — there is no distinction, and no
 * carrying. Multiplication is done through logarithm tables: {@code a * b} is
 * {@code exp(log(a) + log(b))}.
 */
final class GaloisField256 {

    /** The Data Matrix field generator polynomial. */
    private static final int PRIMITIVE = 0x12D;

    /** The exponent of the generator used as the first root — Data Matrix counts from 1, not 0. */
    static final int GENERATOR_BASE = 1;

    private static final int[] EXP = new int[512];
    private static final int[] LOG = new int[256];

    static {
        int x = 1;
        for (int i = 0; i < 255; i++) {
            EXP[i] = x;
            LOG[x] = i;
            x <<= 1;
            if (x >= 256) x ^= PRIMITIVE;
        }
        // Doubled so a product's exponent sum never needs a modulo before lookup.
        for (int i = 255; i < 512; i++) EXP[i] = EXP[i - 255];
    }

    private GaloisField256() {}

    /** Addition and subtraction are the same operation in a binary field. */
    static int add(int a, int b) {
        return a ^ b;
    }

    static int multiply(int a, int b) {
        if (a == 0 || b == 0) return 0;
        return EXP[LOG[a] + LOG[b]];
    }

    /** Returns {@code a} divided by {@code b}. */
    static int divide(int a, int b) {
        if (b == 0) throw new ArithmeticException("division by zero in GF(256)");
        if (a == 0) return 0;
        return EXP[LOG[a] - LOG[b] + 255];
    }

    /** Returns the generator raised to {@code power}, for any sign of exponent. */
    static int exp(int power) {
        return EXP[Math.floorMod(power, 255)];
    }

    /** Returns the multiplicative inverse of {@code a}. */
    static int inverse(int a) {
        if (a == 0) throw new ArithmeticException("zero has no inverse in GF(256)");
        return EXP[255 - LOG[a]];
    }

    /** Evaluates a polynomial, coefficients highest-order first, at {@code x}. */
    static int evaluate(int[] coefficients, int x) {
        int result = 0;
        for (int coefficient : coefficients) {
            result = add(multiply(result, x), coefficient);   // Horner's method
        }
        return result;
    }
}
